<script>
    jQuery(function ($) {
        let showFormBtn = false;

        $('.checkboxes__agreement-title').on('click', function (e) {

            if ( $("#termsAgreement").is(':checked') && $("#mailingAgreement").is(':checked') ) {
                showFormBtn = true;
            } else {
                showFormBtn = false;
            }


            if (showFormBtn == true) {
                $('.welcom-unisender__btn').prop( "disabled", false );
            } else {
                $('.welcom-unisender__btn').prop( "disabled", true );
            }

        });

        $('.welcom-unisender__btn').on('click', function () {
            if (showFormBtn == true) {
                $.cookie('SMORODINA_WELCOME_POPUP_SIGNED', "1", {  path: '/' });

                //  метрика: подписка
                if (typeof ym != 'undefined') {
                    ym('76511557', 'reachGoal', 'welcom-unisender__signed');
                }
            }
        });

        $( ".welcom-unisender__close").on('click', function () {
            $(this).parents('.welcom-unisender__wrapper').fadeOut(200);

            //  метрика: Попап закрыт
            if (typeof ym != 'undefined') {
                ym('76511557', 'reachGoal', 'welcom-unisender__close');
            }
        });
        $(document).mouseup(function (e) {
            const div = $(".welcom-unisender__block");
            if (!div.is(e.target) && div.has(e.target).length === 0) {
                $('.welcom-unisender__wrapper').fadeOut(200);

                //  метрика: Попап закрыт
                if (typeof ym != 'undefined') {
                    ym('76511557', 'reachGoal', 'welcom-unisender__close');
                }
            }
        });


        // появление
        function showPopup() {
            $('.welcom-unisender__wrapper').fadeIn(200);

            // метрика: Попап показан
            if (typeof ym != 'undefined') {
                ym('76511557', 'reachGoal', 'welcom-unisender__showed');
            }
        }

        // повторное появление тому же пользователю через 48 часов
        function resetCookie() {
            setTimeout(
                function () {
                    $.cookie('SMORODINA_WELCOME_POPUP', null);
                },
                172800000
            );
        }


        if ($.cookie('SMORODINA_WELCOME_POPUP') != "1") {
            // показать попап через 60 секунд
            setTimeout(
                function () {
                    showPopup();
                    $.cookie('SMORODINA_WELCOME_POPUP', "1", {  path: '/' });

                    // если не подписался - то сбросить куки для повторного показа
                    if ($.cookie('SMORODINA_WELCOME_POPUP_SIGNED') != "1") {
                        resetCookie();
                    }
                },
                60000
            );
        }

    });
</script>
<script>
document.addEventListener('DOMContentLoaded', () => {
    const csrf = document.querySelector('meta[name="csrf-token"]').getAttribute('content');

    function updateCartIcon(total) {
        const cartCount = document.querySelector('.count_cart');
        if (cartCount) {
            cartCount.textContent = total;
            cartCount.style.display = total > 0 ? 'inline' : 'none';
        }
    }

    function updateCardUI(card, count) {
        const textBlock = card.querySelector('.product-card__text');
        const addBlock = card.querySelector('.product-card__add-block');
        const countBlock = card.querySelector('.product-card__count');
        const countVal = card.querySelector('.product-card__count__value');
        const countSub = card.querySelector('.product-card__text__price-quantity');
        const priceEl = card.querySelector('.product-card__text__price-current');
        const unit = parseInt(priceEl.dataset.currentPrice || 0);
        const btn = card.querySelector('.product-card__btn-js');
        const btnText = btn?.querySelector('.product-card__btn-text');

        if (count > 0) {
            textBlock?.classList.add('product-card__text_active');
            addBlock?.classList.add('product-card__add-block_active');
            countBlock?.classList.add('product-card__count_active');
            btn?.classList.add('add_to_cart');

            countVal.textContent = count;
            countSub.textContent = 'x' + count;
            priceEl.textContent = (unit * count).toLocaleString('ru-RU') + ' ₽';

            if (btnText) {
                btnText.textContent = 'В корзине';
                btn.setAttribute('disabled', true);
                btn.style.pointerEvents = 'none'; // запретить любые клики
                btn.style.cursor = 'default';     // убрать "палец"
            }
        } else {
            textBlock?.classList.remove('product-card__text_active');
            addBlock?.classList.remove('product-card__add-block_active');
            countBlock?.classList.remove('product-card__count_active');
            btn?.classList.remove('add_to_cart');

            countVal.textContent = '0';
            countSub.textContent = '';
            priceEl.textContent = unit.toLocaleString('ru-RU') + ' ₽';

            if (btnText) {
                btnText.textContent = 'В корзину';
                btn.removeAttribute('disabled');
                btn.style.pointerEvents = 'auto';
                btn.style.cursor = 'pointer';
            }
        }
    }

    // Кнопка "в корзину"
    document.querySelectorAll('.product-card__btn-js').forEach(btn => {
        btn.addEventListener('click', () => {
            const card = btn.closest('.product-card');
            const id = card.dataset.id;
            const countVal = card.querySelector('.product-card__count__value');
            let quantity = parseInt(countVal.textContent) || 1;

            fetch('/cart/add', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-CSRF-TOKEN': csrf
                },
                body: JSON.stringify({ id, quantity })
            }).then(res => res.json())
              .then(data => {
                  updateCardUI(card, quantity);
                  updateCartIcon(data.total);
              });
        });
    });

    // + и - кнопки
    document.querySelectorAll('.product-card__count__minus, .product-card__count__plus').forEach(btn => {
        btn.addEventListener('click', () => {
            const card = btn.closest('.product-card');
            const id = card.dataset.id;
            const countVal = card.querySelector('.product-card__count__value');
            let quantity = parseInt(countVal.textContent) || 0;

            if (btn.dataset.type === 'plus') quantity++;
            if (btn.dataset.type === 'minus') quantity = Math.max(0, quantity - 1);

            fetch('/cart/update', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-CSRF-TOKEN': csrf
                },
                body: JSON.stringify({ id, quantity })
            }).then(res => res.json())
              .then(data => {
                  updateCardUI(card, quantity);
                  updateCartIcon(data.total);
              });
        });
    });
});
</script>
@if (!request()->is('cabinet') || request('view') !== 'favorites')
<script>
document.addEventListener('DOMContentLoaded', function () {
    document.querySelectorAll('.product-card__favorite').forEach(el => {
        el.addEventListener('click', function () {
            const productId = this.dataset.productId;

            fetch('/favorite/toggle', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content
                },
                body: JSON.stringify({ product_id: productId })
            })
            .then(res => res.json())
            .then(data => {
                if (data.status === 'added') {
                    this.classList.add('product-card__favorite_active');
                } else {
                    this.classList.remove('product-card__favorite_active');
                }
            });
        });
    });
});
</script>
